import { useEffect, useState } from "react";
import {
    addDoc,
      collection,
        onSnapshot,
          orderBy,
            query,
              serverTimestamp,
                
                  
                    
                    } from "firebase/firestore";


            import { auth, db } from "./firebase";

            import Login from "./Login";
            import Registration from "./Registration";
            import Verification from "./Verification";
            import Confirmation from "./Confirmation";
            import Home from "./Home";
            import type { Item } from "./Home";
            import PostItem from "./PostItem";
            import ItemDetails from "./ItemDetails";
            import Chat from "./Chat";
             import SellerInbox from "./SellerInbox";
             

          type Step =
            | "login"
              | "registration"
                | "verification"
                  | "confirmation"
                    | "home"
                      | "postItem"
                        | "itemDetails"
                          | "chat"
                            | "sellerInbox";

                            export default function App() {
                              const [step, setStep] = useState<Step>("login");

                                const [registeredEmail, setRegisteredEmail] = useState("");

                                  const [items, setItems] = useState<Item[]>([]);
                                    const [itemsLoading, setItemsLoading] = useState(true);
                                      const [itemsError, setItemsError] = useState("");

                                        const [selectedItem, setSelectedItem] = useState<Item | null>(null);
                                          const [chatItem, setChatItem] = useState<Item | null>(null);

                                            // Load saved listings from Firestore.
                                              useEffect(() => {
                                                  const itemsQuery = query(
                                                        collection(db, "items"),
                                                              orderBy("createdAt", "desc")
                                                                  );

                                                                      const unsubscribe = onSnapshot(
                                                                            itemsQuery,
                                                                                  (snapshot) => {
                                                                                          const savedItems: Item[] = snapshot.docs.map((document) => {
                                                                                                    const data = document.data();

                                                                                                              return {
                                                                                                                  id: document.id,
                                                                                                                    sellerId: String(data.sellerId ?? ""),
                                                                                                                      title: String(data.title ?? ""),
                                                                                                                        category: String(data.category ?? ""),
                                                                                                                          price: String(data.price ?? ""),
                                                                                                                            location: String(data.location ?? ""),
                                                                                                                              description: String(data.description ?? ""),
                                                                                                                                image: String(data.image ?? ""),
                                                                                                                                };
                                                                                                                                                                                                                                          });

                                                                                                                                                                                                                setItems(savedItems);
                                                                                                                                                                                                                        setItemsError("");
                                                                                                                                                                                                                                setItemsLoading(false);
                                                                                                                                                                                                                                      },
                                                                                                                                                                                                                                            (error) => {
                                                                                                                                                                                                                                                    console.error("Error loading listings:", error);
                                                                                                                                                                                                                                                            setItemsError(
                                                                                                                                                                                                                                                                      "Could not load listings. Check your Firestore database and security rules."
                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                      setItemsLoading(false);
                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                    return unsubscribe;
                                                                                                                                                                                                                                                                                                      }, []);

                                                                                                                                                                                                                                                                                                        // Login successfully.
                                                                                                                                                                                                                                                                                                          const handleLogin = () => {
                                                                                                                                                                                                                                                                                                              setStep("home");
                                                                                                                                                                                                                                                                                                                };

                                                                                                                                                                                                                                                                                                                  // Registration successfully submitted.
                                                                                                                                                                                                                                                                                                                    const handleRegistered = (email: string) => {
                                                                                                                                                                                                                                                                                                                        setRegisteredEmail(email);
                                                                                                                                                                                                                                                                                                                            setStep("verification");
                                                                                                                                                                                                                                                                                                                              };

                                                                                                                                                                                                                                                                                                                                // Email verification completed.
                                                                                                                                                                                                                                                                                                                                  const handleVerified = () => {
                                                                                                                                                                                                                                                                                                                                      setStep("confirmation");
                                                                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                                                                          // Confirmation completed.
                                                                                                                                                                                                                                                                                                                                            const handleConfirmed = () => {
                                                                                                                                                                                                                                                                                                                                                setStep("home");
                                                                                                                                                                                                                                                                                                                                                  };

                                                                                                                                                                                                                                                                                                                                                    // Open the item posting form.
                                                                                                                                                                                                                                                                                                                                                      const handlePostItem = () => {
                                                                                                                                                                                                                                                                                                                                                          setStep("postItem");
                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                              // Save a new item to Firestore.
                                                                                                                                                                                                                                                                                                                                                                const handleItemPosted = async (newItem: Item) => {
                                                                                                                                                                                                                                                                                                                                                                    try {
                                                                                                                                                                                                                                                                                                                                                                          setItemsError("");

                                                                                                                       const currentUser = auth.currentUser;
                                                                                                                       
                                                                                                                       if (!currentUser) {
                                                                                                                         setItemsError("Please log in before posting an item.");
                                                                                                                           return;
                                                                                                                           }                                                                                                                                                                                                                                                         await addDoc(collection(db, "items"), {
                                                                                                                                                                                                                                                                                                                                                                                        title: newItem.title,
                                                                                                                                                                                                                                                                                                                                                                                                category: newItem.category,
                                                                                                                                                                                                                                                                                                                                                                                                        price: newItem.price,
                                                                                                                                                                                                                                                                                                                                                                                                                location: newItem.location,
                                                                                                                                                                                                                                                                                                                                                                                                                        description: newItem.description,
                                                                                                                                                                                                                                                                                                                                                                                                                                image: newItem.image,
                                                                                                                                                                               sellerId: currentUser.uid,                                                                                                                                                                                                                                                         createdAt: serverTimestamp(),
                                                                                                                                                                                                                                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                                                                                                                                                                                                                                    setStep("home");
                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                              console.error("Error saving item:", error);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                    setItemsError(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "Your item could not be saved. Check your internet connection and Firestore security rules."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // Open item details.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const handleViewItem = (item: Item) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                setSelectedItem(item);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    setStep("itemDetails");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Return to Home.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const handleBack = () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              setStep("home");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // Open chat with the seller.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const handleChat = () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (selectedItem) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              setChatItem(selectedItem);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    setStep("chat");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {/* LOGIN */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {step === "login" && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Login
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onLoggedIn={handleLogin}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        onCreateAccount={() => setStep("registration")}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {/* REGISTRATION */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {step === "registration" && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Registration
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        onRegistered={handleRegistered}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onLogin={() => setStep("login")}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {/* EMAIL VERIFICATION */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {step === "verification" && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Verification
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              email={registeredEmail}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        onVerified={handleVerified}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {/* CONFIRMATION */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {step === "confirmation" && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Confirmation onContinue={handleConfirmed} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {/* HOME */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {step === "home" && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {itemsLoading && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p style={{ textAlign: "center", padding: "15px" }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Loading listings...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {itemsError && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  color: "red",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  background: "#ffebee",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  padding: "12px",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  margin: "10px",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  borderRadius: "8px",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {itemsError}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Home
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    items={items}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onPostItem={handlePostItem}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        onViewItem={handleViewItem}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onOpenSellerInbox={() => setStep("sellerInbox")}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          />                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {/* POST AN ITEM */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {step === "postItem" && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <PostItem
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onBack={handleBack}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              onItemPosted={handleItemPosted}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            )}

                                                            {/* ITEM DETAILS */}
                                                            {step === "itemDetails" && selectedItem && (
                                                              <ItemDetails
                                                                  item={selectedItem}
                                                                      onBack={handleBack}
                                                                          onContactSeller={handleChat}
                                                                            />
                                                                            )}
                                                                            
                                                                            {/* CHAT */}
                                                                            {step === "chat" && chatItem !== null && (
                                                                              <Chat
                                                                                  item={chatItem}
                                                                                      onBack={() => setStep("itemDetails")}
                                                                                        />
                                                                                        )}
                                                                                        
                                                         {/* SELLER INBOX */}
                                                         {step === "sellerInbox" && (
                                                           <SellerInbox
                                                               onBack={() => setStep("home")}
                                                                   onOpenConversation={(conversation) => {
                                                                         const relatedItem = items.find(
                                                                                 (item) => item.id === conversation.itemId
                                                                                       );
                                                                                       
                                                                                             if (!relatedItem) {
                                                                                                     alert("The item for this conversation could not be found.");
                                                                                                             return;
                                                                                                                   }
                                                                                                                   
                                                                                                                         setChatItem(relatedItem);
                                                                                                                               setStep("chat");
                                                                                                                                   }}
                                                                                                                                     />
                                                                                                                                     )}                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           </div>
                                                                                                                                    );
                                                                                                                                    }                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      